<p class="muted">Article views count page requests, not unique readers. Scheduled articles become public at their publication time; the table below groups their saved editorial status.</p><div class="quick-grid"><section class="panel"><h2>News by status</h2><table><thead><tr><th>Status</th><th>Stories</th><th>Page views</th></tr></thead><tbody><?php foreach ($stats as $row): ?><tr><td><?= e($row['status']) ?></td><td><?= number_format($row['total']) ?></td><td><?= number_format($row['views']) ?></td></tr><?php endforeach ?></tbody></table></section><section class="panel"><h2>Classifieds by status</h2><table><thead><tr><th>Status</th><th>Advertisements</th></tr></thead><tbody><?php foreach ($adStats as $row): ?><tr><td><?= e($row['status']) ?></td><td><?= number_format($row['total']) ?></td></tr><?php endforeach ?></tbody></table></section></div><?php if ($paymentStats): ?><section class="panel"><h2>Recorded payments (LKR)</h2><div class="stat-grid"><?php foreach ($paymentStats as $row): ?><div class="stat"><span><?= e(ucfirst($row['status'])) ?></span><strong><?= number_format($row['total'],2) ?></strong></div><?php endforeach ?></div></section><?php endif ?><section class="panel"><h2>Most-read stories</h2><table><thead><tr><th>Story</th><th>Page views</th></tr></thead><tbody><?php foreach ($top as $row): ?><tr><td><a href="<?= e(url('admin/articles/edit/'.$row['id'])) ?>"><?= e($row['title_en'] ?: ($row['title_si'] ?: $row['title_ta'])) ?></a></td><td><?= number_format($row['views']) ?></td></tr><?php endforeach ?></tbody></table></section>
